export function unitOf(lessonId) {
  return UNITS.find((u) => u.lessons.includes(lessonId));
}

export function allLearnedVocab(uptoLessonIndex) {
  const words = [];
  CURRICULUM.lessons.slice(0, uptoLessonIndex + 1).forEach((l) =>
    l.vocab.forEach((v) => words.push(v))
  );
  return words;
}

export function gradeBand(score) {
  if (score >= 90) return { ar: "مُمْتَاز", color: "#B9862F" };
  if (score >= 80) return { ar: "جَيِّد جِدًّا", color: "#0E5237" };
  if (score >= 70) return { ar: "جَيِّد", color: "#0E5237" };
  if (score >= 60) return { ar: "مَقْبُول", color: "#6B7A6E" };
  return { ar: "رَاسِب", color: "#A34038" };
}
